const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pointSE = ee.Geometry.Point([121.964992, 24.835948]); // Southeastern coast
  const pointNW = ee.Geometry.Point([121.934522, 24.846073]); // Northwestern coast
  const dateStart = '2021-09-29';
  const dateEnd = '2021-09-30';

  // 2. Data Acquisition & Cloud Masking
  // A function to mask clouds using the S2 QA band.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
      qa.bitwiseAnd(cirrusBitMask).eq(0)
    );
    return image.updateMask(mask).divide(10000); // Scale factor for SR
  }

  // Load Sentinel-2 Surface Reflectance collection.
  let s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateStart, dateEnd)
    .filterBounds(pointSE.union(pointNW));

  // 3. Data Availability Check
  const collectionSize = s2_collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-2 images found for the specified date.");
    console.log("A: No"); // In this context, C1 means we can't compare, but the question requires A/B. The premise cannot be confirmed.
    return;
  }

  const image = s2_collection.map(maskS2clouds).median();

  // 4. Calculation & Validation
  // "Lighter blue coloration" implies higher reflectance in the blue band.
  // We will check the value of the Blue band (B2).
  const scale = 10; // Use native resolution for point sampling
  const reducer = ee.Reducer.first();

  const valueSE = image.reduceRegion({
    reducer: reducer,
    geometry: pointSE,
    scale: scale
  }).get('B2');

  const valueNW = image.reduceRegion({
    reducer: reducer,
    geometry: pointNW,
    scale: scale
  }).get('B2');

  // Use .getInfo() together to be more efficient
  const results = ee.Dictionary({ 'SE': valueSE, 'NW': valueNW }).getInfo();
  const valSE = results.SE;
  const valNW = results.NW;

  // 5. Validation & Final Answer
  if (valSE === null || valNW === null) {
    console.log("Data unavailable at one or both points (likely due to clouds).");
    console.log(`SE Point (Blue Band): ${valSE}`);
    console.log(`NW Point (Blue Band): ${valNW}`);
    console.log("C2: No Valid Pixels");
    return;
  }

  console.log(`Image Count: ${collectionSize}`);
  console.log(`Southeastern Water (Blue Reflectance): ${valSE.toFixed(4)}`);
  console.log(`Northwestern Water (Blue Reflectance): ${valNW.toFixed(4)}`);

  if (valSE > valNW) {
    console.log("Southeastern water shows higher blue reflectance, indicating a lighter color.");
    console.log("A: Yes");
  } else {
    console.log("Southeastern water does not show higher blue reflectance.");
    console.log("B: No");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or Analysis failed: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
  }
}

initEE();
